            if box <= cells:
                tiles.append((box, 1))
            for missing in box:
                triomino = box - {missing}
                if triomino <= cells:
                    tiles.append((triomino, 0))
    by_cell = {cell: [] for cell in cells}
    for piece, is_square in tiles:
        for cell in piece:
            by_cell[cell].append((piece, is_square))

    memo = {}
    def solve(remaining):
        if not remaining:
            return (0, [])
        key = frozenset(remaining)
        if key in memo:
            return memo[key]
        cell = min(remaining, key=lambda x: sum(1 for p, _ in by_cell[x] if p <= remaining))
        best = (-1, None)
        options = sorted((item for item in by_cell[cell] if item[0] <= remaining),
                         key=lambda item: (-item[1], min(item[0])))
        for piece, is_square in options:
            count, rest = solve(remaining - piece)
            if rest is not None and count + is_square > best[0]:
                best = (count + is_square, [(piece, is_square)] + rest)
        memo[key] = best
        return best

    _, pieces = solve(cells)
    out = [[0] * w for _ in range(h)]
    for piece, is_square in pieces or []:
        if is_square:
            color = 1
        else:
